import{_ as t,c as s,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"诚斋易传卷二十","description":"诚斋易传 - 诚斋易传卷二十","frontmatter":{"title":"诚斋易传卷二十","description":"诚斋易传 - 诚斋易传卷二十"},"headers":[],"relativePath":"zh/classics/chengzhai/021.md","filePath":"zh/classics/chengzhai/021.md"}'),r={name:"zh/classics/chengzhai/021.md"};function c(i,a,o,p,d,h){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"诚斋易传卷二十",tabindex:"-1"},[l("诚斋易传卷二十 "),e("a",{class:"header-anchor",href:"#诚斋易传卷二十","aria-label":"Permalink to “诚斋易传卷二十”"},"​")],-1),e("p",null,"钦定四库全书",-1),e("p",null,"宋杨万里撰",-1),e("p",null,"有天地，然后万物生焉。盈天地之间者唯万物，故受之以「屯」。「屯」者，盈也。屯者，物之始生也。物生必蒙，故受之以「蒙」。「蒙」者，蒙也，物之稚也。物稚不可不养也，故受之以「需」。「需」者，饮食之道也。饮食必有讼，故受之以「讼」。讼必有众起，故受之以「师」。「师」者，众也。众必有所比，故受之以「比」。「比」者，比也。比必有所畜，故受之以「小畜」。物畜然后有礼，故受之以「履」。履而泰，然后安，故受之以「泰」。「泰」者，通也。物不可以终通，故受之以「否」。物不可以终否，故受之以「同人」。与人同者，物必归焉，故受之以「大有」。有大者不可以盈，故受之以「谦」。有大而能谦必豫，故受之以「豫」。豫必有随，故受之以「随」。以喜随人者必有事，故受之以「蛊」。「蛊」者，事也。有事而后可大，故受之以「临」。「临」者，大也。物大然后可观，故受之以「观」。可观而后有所合，故受之以「噬嗑」。「嗑」者，合也。物不可以苟合而已，故受之以「贲」；「贲」者，饰也。致饰然后亨则尽矣，故受之以「剥」。「剥」者，剥也。物不可以终尽，剥穷上反下，故受之以「复」。复则不妄矣，故受之以「无妄」。有无妄然后可畜，故受之以「大畜」。物畜然后可养，故受之以「颐」。「颐」者，养也。不养则不可动，故受之以「大过」。物不可以终过，故受之以「坎」。「坎」者，陷也。陷必有所丽，故受之以「离」。「离」者，丽也。",-1),e("p",null,"有天地然后有万物，有万物然后有男女，有男女然后有夫妇，有夫妇然后有父子，有父子然后有君臣，有君臣然后有上下，有上下然后礼义有所错。夫妇之道不可以不久也，故受之以「恒」。「恒」者，久也。物不可以久居其所，故受之以「遁」。「遁」者，退也。物不可以终遁，故受之以「大壮」。物不可以终壮，故受之以「晋」。「晋」者，进也。进必有所伤，故受之以「明夷」。「夷」者，伤也。伤于外者必反其家，故受之以「家人」。家道穷必乖，故受之以「睽」。「睽」者，乖也。乖必有难，故受之以「蹇」；「蹇」者，难也。物不可以终难，故受之以「解」。「解」者，缓也。缓必有所失，故受之以「损」。损而不已必益，故受之以「益」。益而不已必决，故受之以「夬」。「夬」者，决也。决必有所遇，故受之以「姤」。「姤」者，遇也。物相遇而后聚，故受之以「萃」。「萃」者，聚也。聚而上者谓之升，故受之以「升」。升而不已必因，故受之以「困」。困乎上者必反下，故受之以「井」。井道不可不革，故受之以「革」。革物者莫若鼎，故受之以鼎。主器者莫若长子，故受之以震。震者，动也。物不可以终动，止之，故受之以艮；艮者，止也。物不可以终止，故受之以渐。渐者，进也。进必有所归，故受之以归妹。得其所归者必大，故受之以丰。丰者，大也。穷大者必失其居，故受之以旅。旅而无所容，故受之以巽。巽者，入也。入而后说之，故受之以兑；兑者，说也。说而后散之，故受之以涣；涣者，离也。物不可以终离，故受之以节。节而信之，故受之以中孚。有其信者必行之，故受之以小过。有过物者必济，故受之以既济。物不可穷也，故受之以未济终焉。程氏曰：天地万物之本，夫妇人伦之始，所以上经首乾、坤，下经首咸，继以恒也。杨氏曰：乾、坤，万物父母；咸、恒，人之父母。",-1),e("p",null,"乾刚坤柔，比乐师忧。临、观之义，或与或求。屯见而不失其居。蒙杂而著。震，起也；艮，止也。损、益，盛衰之始也。大畜，时也；无妄，灾也。萃聚，而升不来也。谦轻，而豫怠也。噬嗑，食也；贲，无色也。兑见，而巽伏也。随，无故也。蛊则饬也。剥，烂也；复，反也。晋，昼也；明夷，诛也。井通，而困相遇也。咸，速也；恒，久也。涣，离也。节，止也。解，缓也。蹇，难也。睽，外也；家人，内也。否、泰，反其类也。大壮则止，遁则退也。大有，众也，同人，亲也。革，去故也。鼎，取新也。小过，过也，中孚，信也。丰，多故也，亲寡旅也。离上而坎下也。小畜，寡也。履，不处也。需，不进也。讼，不亲也。大过，颠也。姤，遇也，柔遇刚也。渐，女归待男行也。颐，养正也。既济，定也。归妹，女之终也。未济，男之穷也。夬，决也，刚决柔也。君子道长，小人道忧也。诚斋易传卷二十",-1)])])}const _=t(r,[["render",c]]);export{u as __pageData,_ as default};
